import{_ as a,o as i,c as o,ag as l}from"./chunks/framework.DQQHyi2x.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function r(n,e,d,s,c,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Claude Deck are documented here. The format follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>.</p><h2 id="_1-3-0-—-2026-06-08" tabindex="-1">1.3.0 — 2026-06-08 <a class="header-anchor" href="#_1-3-0-—-2026-06-08" aria-label="Permalink to &quot;1.3.0 — 2026-06-08&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Codex CLI support</strong> is now stable enough for daily use: <ul><li>Mixed Claude Code and Codex tmux sessions in Agent Bridge</li><li>Codex spawn, resume, fork, attach, and kill actions</li><li>Provider-aware navigation so Codex users do not land on unsupported Claude-only pages</li></ul></li><li><strong>Codex Config</strong>: <ul><li>Safe TOML editing for whitelisted scalar settings and feature flags</li><li>Dropdowns for known Codex runtime values</li><li>Help tooltips for documented settings and feature flags</li><li>Feature inventory from <code>codex features list</code>, including goals and other enable-flag features</li><li>Profile diagnostics for active/default profiles, profile files, overrides, missing references, and malformed profiles</li></ul></li><li><strong>Codex MCP and Plugins</strong>: <ul><li>MCP inventory from <code>codex mcp list --json</code></li><li>MCP add/remove through the Codex CLI with validation</li><li>Plugin inventory from <code>codex plugin list</code></li><li>Plugin install/remove where the installed Codex CLI exposes safe commands</li></ul></li><li><strong>Codex Backup Export</strong>: <ul><li>Redacted export-only backups for config, profile files, rules, and provider inventory metadata</li></ul></li><li><strong>Projects</strong>: <ul><li>Easier project discovery and directory browsing when adding project paths</li></ul></li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Provider status, capabilities, diagnostics, and normalized provider errors now drive more of the UI.</li><li>The frontend toolchain now uses TypeScript 6, <code>@vitejs/plugin-react</code> 5, updated ESLint tooling, React DOM, PostCSS, Tailwind Merge, and Node types.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Codex auth, history, model cache, SQLite state, prompt text, and raw cache payloads are still excluded from raw viewers and backups.</li><li>Automatic Codex restore remains disabled because exports intentionally omit provider-owned local state.</li></ul><h2 id="_1-2-0-—-2026-04-22" tabindex="-1">1.2.0 — 2026-04-22 <a class="header-anchor" href="#_1-2-0-—-2026-04-22" aria-label="Permalink to &quot;1.2.0 — 2026-04-22&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — live terminal bridge to Claude Code sessions in tmux <ul><li>Multi-terminal grid (up to 4 panes in auto-layout)</li><li>Per-pane read-only/interactive mode, fullscreen, attach/detach</li><li>Session discovery via <code>tmux list-panes</code> with auto-refresh</li><li>Spawn new sessions (plain, worktree, or resume mode)</li><li>Kill sessions with optional worktree cleanup</li><li>WebSocket PTY relay with xterm.js (WebGL rendering)</li></ul></li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CC Bridge</strong> — prevent orphaned <code>tmux attach-session</code> processes on server reload</li><li><strong>CC Bridge</strong> — fix terminal rendering in React StrictMode</li></ul><h2 id="_1-0-0-—-2026-01-22" tabindex="-1">1.0.0 — 2026-01-22 <a class="header-anchor" href="#_1-0-0-—-2026-01-22" aria-label="Permalink to &quot;1.0.0 — 2026-01-22&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Initial release of Claude Deck</li><li><strong>Dashboard</strong> — configuration status and usage overview</li><li><strong>MCP Server Management</strong> — add, edit, test, configure servers (global + project)</li><li><strong>Commands</strong> — create and manage slash commands</li><li><strong>Plugins</strong> — create, install, and manage plugins</li><li><strong>Hooks</strong> — configure event hooks for Claude Code lifecycle</li><li><strong>Permissions</strong> — manage allow/deny rules for tools</li><li><strong>Backup &amp; Restore</strong> — full configuration backup and restore</li><li><strong>Project Management</strong> — project-specific configurations</li><li><strong>Usage Tracking</strong> — token usage and cost visualization</li></ul><h3 id="technical" tabindex="-1">Technical <a class="header-anchor" href="#technical" aria-label="Permalink to &quot;Technical&quot;">​</a></h3><ul><li>FastAPI backend with async SQLAlchemy + SQLite</li><li>React frontend with TypeScript, Vite, and shadcn/ui</li><li>RESTful API at <code>/api/v1/</code></li></ul><hr><p>See the full changelog on <a href="https://github.com/adrirubio/claude-deck/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">GitHub</a>.</p>',21)])])}const f=a(t,[["render",r]]);export{g as __pageData,f as default};
